using Microsoft.Extensions.Logging.Abstractions;using StockSyncAI.Api.Configuration;using StockSyncAI.Api.Database;using StockSyncAI.Api.Models;
namespace StockSyncAI.Tests.Database;
public sealed class InvoicePostingRepositoryTests:IDisposable
{
 private readonly string dir=Path.Combine(Path.GetTempPath(),$"stocksync-posting-{Guid.NewGuid():N}");
 [Fact] public async Task Repository_GuardsTransitionsAndRecoversUnknownOutcome(){var(repo,invoice)=await Create();var f=new string('a',64);var p=await repo.PrepareAsync(invoice,f,"{}",DateTimeOffset.UtcNow);Assert.Equal(PostingStates.Prepared,p.State);Assert.NotNull(await repo.TryStartAsync(p.Id,DateTimeOffset.UtcNow));Assert.Null(await repo.TryStartAsync(p.Id,DateTimeOffset.UtcNow));Assert.Equal(1,(await repo.RecoverInterruptedAsync(DateTimeOffset.UtcNow)).RecoveredCount);var u=await repo.GetAsync(invoice,f);Assert.Equal(PostingStates.OutcomeUnknown,u!.State);var retry=await repo.PrepareAsync(invoice,f,"changed",DateTimeOffset.UtcNow);Assert.Equal(PostingStates.OutcomeUnknown,retry.State);Assert.Equal("{}",retry.SnapshotJson);}
 [Fact] public async Task PostedVersion_CannotBePreparedOrStartedAgain(){var(repo,invoice)=await Create();var f=new string('b',64);var p=await repo.PrepareAsync(invoice,f,"{}",DateTimeOffset.UtcNow);await repo.TryStartAsync(p.Id,DateTimeOffset.UtcNow);await repo.SetOutcomeAsync(p.Id,PostingStates.Posted,null,"{}",DateTimeOffset.UtcNow,DateTimeOffset.UtcNow);Assert.Equal(PostingStates.Posted,(await repo.PrepareAsync(invoice,f,"x",DateTimeOffset.UtcNow)).State);Assert.Null(await repo.TryStartAsync(p.Id,DateTimeOffset.UtcNow));}
 [Fact] public async Task AttemptsAndEvents_AreAppendOnlyAcrossSafeRetry(){var(repo,invoice)=await Create();var p=await repo.PrepareAsync(invoice,new string('c',64),"immutable",DateTimeOffset.UtcNow);var first=await repo.TryStartAsync(p.Id,DateTimeOffset.UtcNow);Assert.NotNull(first);await repo.SetOutcomeAsync(p.Id,PostingStates.FailedSafeToRetry,"confirmed rollback",null,null,DateTimeOffset.UtcNow);var prepared=await repo.PrepareAsync(invoice,new string('c',64),"immutable",DateTimeOffset.UtcNow);var second=await repo.TryStartAsync(prepared.Id,DateTimeOffset.UtcNow);Assert.NotNull(second);Assert.Equal(2,second.AttemptNumber);var attempts=await repo.ListAttemptsAsync(p.Id);Assert.Equal(2,attempts.Count);Assert.Contains(attempts,x=>x.Id==first.Id&&x.TransactionOutcome==PostingTransactionOutcomes.RolledBack);Assert.Contains(attempts,x=>x.Id==second.Id&&x.TransactionOutcome==PostingTransactionOutcomes.InProgress);Assert.True((await repo.ListEventsAsync(p.Id)).Count>=5);Assert.Equal("immutable",(await repo.GetAsync(invoice,new string('c',64)))!.SnapshotJson);}
 [Fact] public async Task InvalidTransitions_AreRejected(){var(repo,invoice)=await Create();var p=await repo.PrepareAsync(invoice,new string('d',64),"{}",DateTimeOffset.UtcNow);await Assert.ThrowsAsync<InvalidOperationException>(()=>repo.SetOutcomeAsync(p.Id,PostingStates.Posted,null,"{}",DateTimeOffset.UtcNow,DateTimeOffset.UtcNow));await Assert.ThrowsAsync<ArgumentOutOfRangeException>(()=>repo.SetOutcomeAsync(p.Id,PostingStates.Prepared,null,null,null,DateTimeOffset.UtcNow));}
 [Fact] public async Task StartupRecovery_IsIdempotentAndPreservesEvidence(){var(repo,invoice)=await Create();var p=await repo.PrepareAsync(invoice,new string('e',64),"{}",DateTimeOffset.UtcNow);var attempt=await repo.TryStartAsync(p.Id,DateTimeOffset.UtcNow);Assert.NotNull(attempt);Assert.Equal(1,(await repo.RecoverInterruptedAsync(DateTimeOffset.UtcNow)).RecoveredCount);Assert.Equal(0,(await repo.RecoverInterruptedAsync(DateTimeOffset.UtcNow)).RecoveredCount);var events=await repo.ListEventsAsync(p.Id);Assert.Single(events,x=>x.EventType==PostingRecoveryEventTypes.StartupInterruptedAttempt);Assert.Equal(PostingTransactionOutcomes.Unknown,Assert.Single(await repo.ListAttemptsAsync(p.Id)).TransactionOutcome);}
 [Fact] public async Task OperatorDecision_IsIdempotentAndDoesNotChangeTechnicalOutcome(){var(repo,invoice)=await Create();var p=await repo.PrepareAsync(invoice,new string('f',64),"{}",DateTimeOffset.UtcNow);await repo.TryStartAsync(p.Id,DateTimeOffset.UtcNow);await repo.SetOutcomeAsync(p.Id,PostingStates.OutcomeUnknown,"unknown",null,null,DateTimeOffset.UtcNow);var request=Guid.NewGuid();var first=await repo.RecordDecisionAsync(p.Id,request,PostingReconciliationDecisions.ReportedPosted,"Observed in POS during manual review.",DateTimeOffset.UtcNow);var repeated=await repo.RecordDecisionAsync(p.Id,request,PostingReconciliationDecisions.ReportedPosted,"ignored duplicate",DateTimeOffset.UtcNow);Assert.Equal(first.Id,repeated.Id);Assert.Single(await repo.ListDecisionsAsync(p.Id));Assert.Equal(PostingStates.OutcomeUnknown,(await repo.GetByIdAsync(p.Id))!.State);Assert.Equal(PostingTransactionOutcomes.Unknown,Assert.Single(await repo.ListAttemptsAsync(p.Id)).TransactionOutcome);}
 private async Task<(InvoicePostingRepository,Guid)> Create(){var paths=new ApplicationPaths(dir);var factory=new SqliteConnectionFactory(paths);await new SqliteDatabaseInitializer(paths,factory,NullLogger<SqliteDatabaseInitializer>.Instance).InitializeAsync();var id=Guid.NewGuid();await new InvoiceRepository(factory).InsertAsync(new(id,"i.pdf",$"{id:N}.pdf",".pdf","application/pdf",1,new string('a',64),DateTimeOffset.UtcNow,InvoiceRecord.UploadedStatus,Guid.NewGuid().ToString("D")));return(new(factory),id);}
 public void Dispose(){Microsoft.Data.Sqlite.SqliteConnection.ClearAllPools();if(Directory.Exists(dir))Directory.Delete(dir,true);}
}
